def last_n_unique(lst: list, n: int) -> list:
    """Return the n distinct values whose last occurrence in lst is latest,
    ordered by the position of that last occurrence (ascending)."""
    last_index: dict = {}
    for i, x in enumerate(lst):
        last_index[x] = i
    top = sorted(last_index, key=lambda x: last_index[x], reverse=True)[:n]
    return sorted(top, key=lambda x: last_index[x])
