from typing import TypeVar

T = TypeVar("T")


def last_n_unique(lst: list[T], n: int) -> list[T]:
    """Return up to n distinct values ordered by their latest occurrence."""
    if n <= 0:
        return []

    seen: list[T] = []
    for value in reversed(lst):
        if value not in seen:
            seen.append(value)

    return list(reversed(seen[:n]))

