from typing import List, Sequence, TypeVar

T = TypeVar("T")


def last_n_unique(lst: Sequence[T], n: int) -> List[T]:
    """Return the n distinct values whose last occurrences are latest in lst.

    The result is ordered by the position of each value's last occurrence in
    lst, from earlier to later among the selected values.
    """
    if n <= 0:
        return []

    seen: List[T] = []
    for x in reversed(lst):
        if x not in seen:
            seen.append(x)

    return list(reversed(seen[:n]))
